// Google News search for our domain, one query per edition (EN, ES, PT).
const Q = 'site:paddockintel.com';
return [
  { json: { ed: 'EN', url: `https://news.google.com/rss/search?q=${encodeURIComponent(Q)}&hl=en-US&gl=US&ceid=US:en` } },
  { json: { ed: 'ES', url: `https://news.google.com/rss/search?q=${encodeURIComponent(Q)}&hl=es-419&gl=US&ceid=US:es-419` } },
  { json: { ed: 'PT', url: `https://news.google.com/rss/search?q=${encodeURIComponent(Q)}&hl=pt-BR&gl=BR&ceid=BR:pt-419` } },
];

// Reports the paddockintel.com stories that appear in Google News search for the first time. The first
// active run sends one baseline email with what is already there. "Lag" is the time from the story's own
// publication date (as Google News shows it) to the hourly run that first saw it, so it is approximate.
const queries = $('Queries').all().map((i) => i.json);
const state = $getWorkflowStaticData('global');
const firstRun = !state.seen;
state.seen = state.seen || {};
const decode = (s) => (s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const pick = (s, re) => { const m = s.match(re); return m ? decode(m[1]).trim() : ''; };
const fresh = []; const counts = {}; const errors = [];
$input.all().forEach((r, i) => {
  const ed = queries[i]?.ed ?? '?';
  const body = String(r.json.body ?? r.json.data ?? '');
  if (r.json.statusCode !== 200 || !body.includes('<rss')) { errors.push(`${ed}: HTTP ${r.json.statusCode ?? r.json.error?.message ?? '?'}`); return; }
  const items = [...body.matchAll(/<item>([\s\S]*?)<\/item>/g)].map(([, s]) => ({
    ed, guid: pick(s, /<guid[^>]*>([\s\S]*?)<\/guid>/), title: pick(s, /<title>([\s\S]*?)<\/title>/).replace(/ - paddockintel\.com$/, ''),
    link: pick(s, /<link>([\s\S]*?)<\/link>/), pub: pick(s, /<pubDate>([\s\S]*?)<\/pubDate>/),
  })).filter((x) => x.guid);
  counts[ed] = items.length;
  for (const it of items) {
    if (state.seen[it.guid]) continue;
    state.seen[it.guid] = Date.now();
    fresh.push(it);
  }
});
const keys = Object.keys(state.seen);
if (keys.length > 5000) keys.sort((a, b) => state.seen[a] - state.seen[b]).slice(0, keys.length - 5000).forEach((k) => delete state.seen[k]);
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
const tally = Object.entries(counts).map(([k, v]) => `${k} ${v}`).join(' · ');
if (firstRun) {
  return [{ json: {
    subject: `Google News · línea base: ${tally}`,
    html: `<p>Desde ahora te aviso cada vez que una nota de paddockintel.com aparece por primera vez en la búsqueda de Google News.</p><p>Ya aparecen: <b>${tally}</b> (resultados de la búsqueda site:paddockintel.com; Google muestra un máximo de 100 por edición).</p>${errors.length ? `<p>Errores: ${esc(errors.join('; '))}</p>` : ''}`,
  } }];
}
if (!fresh.length) return [];
const rows = fresh.sort((a, b) => new Date(b.pub) - new Date(a.pub)).map((x) => {
  const lagH = x.pub ? Math.max(0, (Date.now() - new Date(x.pub)) / 36e5) : null;
  return `<li><b>[${x.ed}]</b> <a href="${esc(x.link)}">${esc(x.title)}</a><br><span style="color:#666">publicada ${esc(x.pub)} · vista en Google News ${lagH === null ? '' : lagH < 48 ? '~' + lagH.toFixed(1) + ' h después' : '~' + (lagH / 24).toFixed(1) + ' días después'}</span></li>`;
}).join('');
return [{ json: {
  subject: `Google News · ${fresh.length} nota${fresh.length === 1 ? '' : 's'} nueva${fresh.length === 1 ? '' : 's'}: ${fresh[0].title}`.slice(0, 160),
  html: `<p>Primera aparición en la búsqueda de Google News:</p><ul>${rows}</ul><p style="color:#888">Total ahora: ${tally}. Aparecer en la búsqueda no garantiza Top Stories ni tráfico; el informe semanal de Search Console mide eso.</p>`,
} }];
